//
// Generated by samples/generate_array_mult.py
//
// Topology: classic Braun array multiplier.
//   - Partial products p[i][j] = a[i] & b[j]    (256 AND gates)
//   - Reduction tree:   240 full_adders in (N-1) x N grid
//   - Final result:     32 bits
//
// Exercises: critical path (carry chain), fanout (each a[i] drives 16 ANDs),
//            longest-path-on-DAG, regular-array structure detection.
//
// License: public-domain textbook design.
// -----------------------------------------------------------------------------

module full_adder (
    input  wire a,
    input  wire b,
    input  wire cin,
    output wire sum,
    output wire cout
);
    wire ab, acin, bcin;
    xor (sum,  a, b, cin);
    and (ab,   a, b);
    and (acin, a, cin);
    and (bcin, b, cin);
    or  (cout, ab, acin, bcin);
endmodule


